def transform(grid):
    h, w = len(grid), len(grid[0])

    sep_rows = {r for r, row in enumerate(grid) if len(set(row)) == 1}
    sep_cols = {c for c in range(w) if len({grid[r][c] for r in range(h)}) == 1}

    def segments(n, separators):
        result, start = [], 0
        for i in range(n):
            if i in separators:
                if start < i:
                    result.append((start, i))
                start = i + 1
        if start < n:
            result.append((start, n))
        return result

    row_blocks = segments(h, sep_rows)
    col_blocks = segments(w, sep_cols)

    cells = [
        grid[r][c]
        for r0, r1 in row_blocks
        for c0, c1 in col_blocks
        for r in range(r0, r1)
        for c in range(c0, c1)
    ]
    background = max(set(cells), key=cells.count)

    out = []
    for r0, r1 in row_blocks:
        row = []
        for c0, c1 in col_blocks:
            other_count = sum(
                grid[r][c] != background
                for r in range(r0, r1)
                for c in range(c0, c1)
            )
            row.append(1 if other_count > 1 else background)
        out.append(row)
    return out
